def transform(g):
    g=[row[:] for row in g]; H,W=len(g),len(g[0])
    pos={}
    for i,r in enumerate(g):
        for j,x in enumerate(r):
            if x: pos.setdefault(x,[]).append((i,j))
    rects={}; scat={}
    for col,ps in pos.items():
        rs=[p[0] for p in ps]; cs=[p[1] for p in ps]
        h=max(rs)-min(rs)+1; w=max(cs)-min(cs)+1
        if len(ps)==2*(h+w)-4: rects[col]=(min(rs),max(rs),min(cs),max(cs))
        else: scat[col]=len(ps)
    # clear scattered
    for col,ps in pos.items():
        if col in scat:
            for i,j in ps: g[i][j]=0
    # pair: rects sorted by interior area asc, colors by count asc
    rl=sorted(rects.items(), key=lambda kv:(kv[1][1]-kv[1][0]-1)*(kv[1][3]-kv[1][2]-1))
    cl=sorted(scat, key=lambda c:scat[c])
    for (col,(r0,r1,c0,c1)),f in zip(rl,cl):
        for i in range(r0+1,r1):
            for j in range(c0+1,c1):
                if (i-(r0+1)+j-(c0+1))%2==0: g[i][j]=f
    return g
